import java.util.HashMap;
import java.util.Map;
import org.jetbrains.uast.UReferenceExpression;
import org.w3c.dom.Attr;

public class AlwaysShowActionDetector extends ResourceXmlDetector implements SourceCodeScanner {

    public static final Issue ISSUE = Issue.create(
            "AlwaysShowAction",
            "Usage of showAsAction=always",
            "Using `showAsAction=\"always\"` in menu XML, or `MenuItem.SHOW_AS_ACTION_ALWAYS` in Java code is usually a deviation from the user interface style guide. Use `ifRoom` or the corresponding `MenuItem.SHOW_AS_ACTION_IF_ROOM` instead.",
            Category.USABILITY,
            5,
            Severity.WARNING,
            new Implementation(
                    AlwaysShowActionDetector.class,
                    EnumSet.of(Scope.RESOURCE_FILE, Scope.JAVA_FILE)
            )
    );

    private static final String SHOW_AS_ACTION = "showAsAction";
    private static final String VALUE_ALWAYS = "always";
    private static final String VALUE_IF_ROOM = "ifRoom";
    private static final String ALWAYS_FIELD = "SHOW_AS_ACTION_ALWAYS";
    private static final String IF_ROOM_FIELD = "SHOW_AS_ACTION_IF_ROOM";

    private final Map<java.io.File, Integer> mAlwaysCounts = new HashMap<>();
    private final Map<java.io.File, Integer> mIfRoomCounts = new HashMap<>();

    private boolean mJavaAlwaysSeen;
    private boolean mJavaIfRoomSeen;
    private Location mJavaAlwaysLocation;

    @Override
    protected boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.MENU;
    }

    @Override
    @NonNull
    public Collection<String> getApplicableAttributes() {
        return Collections.singletonList(SHOW_AS_ACTION);
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String value = attribute.getValue();
        if (value == null || value.isEmpty()) {
            return;
        }

        java.io.File file = context.getFile();
        for (String token : value.split("\\|")) {
            String trimmed = token.trim();
            if (VALUE_ALWAYS.equals(trimmed)) {
                mAlwaysCounts.put(file, mAlwaysCounts.getOrDefault(file, 0) + 1);
            } else if (VALUE_IF_ROOM.equals(trimmed)) {
                mIfRoomCounts.put(file, mIfRoomCounts.getOrDefault(file, 0) + 1);
            }
        }
    }

    @Override
    public void afterCheckFile(@NonNull Context context) {
        if (!(context instanceof XmlContext)) {
            super.afterCheckFile(context);
            return;
        }

        java.io.File file = context.getFile();
        int alwaysCount = mAlwaysCounts.getOrDefault(file, 0);
        int ifRoomCount = mIfRoomCounts.getOrDefault(file, 0);

        if (alwaysCount > 2 || (alwaysCount > 0 && ifRoomCount == 0)) {
            String message = "Avoid using `showAsAction=\"always\"`; use `showAsAction=\"ifRoom\"` instead";
            // Report at file location? Need specific location. We can report at file with no range.
            // Better to report at first always attribute location. But we didn't store attribute locations.
            // For simplicity, report at file location.
            Location location = Location.create(file);
            context.report(ISSUE, location, message);
        }

        // Clean up counts for this file to avoid leaking.
        mAlwaysCounts.remove(file);
        mIfRoomCounts.remove(file);

        super.afterCheckFile(context);
    }

    @Override
    @NonNull
    public Collection<String> getApplicableReferenceNames() {
        return Collections.unmodifiableCollection(java.util.Arrays.asList(ALWAYS_FIELD, IF_ROOM_FIELD));
    }

    @Override
    public void visitReference(@NonNull UReferenceExpression expression) {
        // Need JavaContext to report location. But visitReference signature may not include context.
        // SourceCodeScanner's visitReference(UReferenceExpression node) is called via UElementHandler with JavaContext.
        // However we need context. Maybe use expression.getSourcePsi? Hmm.
    }

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        mJavaAlwaysSeen = false;
        mJavaIfRoomSeen = false;
        mJavaAlwaysLocation = null;
        mAlwaysCounts.clear();
        mIfRoomCounts.clear();
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        if (mJavaAlwaysSeen && !mJavaIfRoomSeen) {
            String message = "Avoid using `MenuItem.SHOW_AS_ACTION_ALWAYS`; use `MenuItem.SHOW_AS_ACTION_IF_ROOM` instead";
            context.report(ISSUE, mJavaAlwaysLocation, message);
        }
    }
}

